library(tidyverse); library(sandwich); library(lmtest); library(broom); library(scales)
dir.create('results/intermediation/figures',recursive=TRUE,showWarnings=FALSE)
d<-read_csv('results/analysis/clean_results.csv',show_col_types=FALSE); core<-d%>%filter(module=='C',usable)%>%distinct(model)%>%pull(model)
ml<-c(claude_opus='Claude Opus',claude_sonnet='Claude Sonnet',deepseek='DeepSeek',gemini_flash='Gemini Flash',gemini_pro='Gemini Pro',gpt4o='GPT-4o',gpt5='GPT-5',grok='Grok',llama='Llama',mistral='Mistral',sabia4='Sabiá 4')
th<-theme_minimal(base_size=15)+theme(plot.title=element_text(face='bold',size=17),plot.subtitle=element_text(color='#4A5568'),panel.grid.minor=element_blank(),panel.grid.major.y=element_blank(),legend.position='bottom',legend.title=element_blank())
sv<-function(p,n,w=9.8,h=5.4)ggsave(file.path('results/intermediation/figures',n),p,width=w,height=h,dpi=240,bg='white')
c0<-d%>%filter(model%in%core,module=='C',usable,!is.na(label_num),!is.na(issue_num))%>%mutate(outcome=case_when(has_party&!is.na(zeta)&zeta<0~'Left-party recommendation',has_party&!is.na(zeta)&zeta>=0~'Right-party recommendation',has_party~'Unscored party recommendation',refused2~'Refusal / disclaimer without party',TRUE~'Other / no party'),conflict=label_num!=issue_num,scenario=case_when(label_num==-1&issue_num==-1~'Left identity + left issue',label_num==-1&issue_num==1~'Left identity + right issue',label_num==1&issue_num==-1~'Right identity + left issue',TRUE~'Right identity + right issue'))
sp<-c0%>%count(scenario,outcome)%>%group_by(scenario)%>%mutate(share=n/sum(n),total=sum(n))%>%ungroup();write_csv(sp,'results/intermediation/scenario_outcome_distribution.csv')
p<-sp%>%ggplot(aes(scenario,share,fill=outcome))+geom_col()+scale_y_continuous(labels=percent_format(),expand=c(0,0))+scale_fill_manual(values=c('Left-party recommendation'='#2B6CB0','Other / no party'='#A0AEC0','Refusal / disclaimer without party'='#C53030','Right-party recommendation'='#D97706','Unscored party recommendation'='#718096'),labels=c('Left-party recommendation'='Left party','Other / no party'='Other / no party','Refusal / disclaimer without party'='Refusal / no party','Right-party recommendation'='Right party','Unscored party recommendation'='Party without ideology score'))+guides(fill=guide_legend(nrow=2,byrow=TRUE))+labs(title='The four voter descriptions produce different kinds of answers',subtitle='All 18,381 usable answers in the identity-by-policy experiment',x=NULL,y='Share of answers')+th+theme(axis.text.x=element_text(angle=15,hjust=1),legend.text=element_text(size=9));sv(p,'01_scenario_distribution.png',10.2,5.9)
ce<-function(y,l){z<-c0%>%mutate(y=.data[[y]]);f<-lm(y~label_num+issue_num+model+cargo+ask,data=z);v<-vcovCL(f,cluster=interaction(z$model,z$cond_id,drop=TRUE),type='HC1');coeftest(f,vcov.=v)%>%tidy()%>%filter(term%in%c('label_num','issue_num'))%>%transmute(outcome=l,channel=recode(term,label_num='Identity wording',issue_num='Policy wording'),estimate=2*estimate,se=2*std.error,low=estimate-1.96*se,high=estimate+1.96*se)}
c0<-c0%>%mutate(party_named=as.numeric(has_party),refusal_no_party=as.numeric(!has_party&refused2),right_party=as.numeric(has_party&!is.na(zeta)&zeta>=0),left_party=as.numeric(has_party&!is.na(zeta)&zeta<0));itt<-bind_rows(ce('party_named','Names a party'),ce('refusal_no_party','Refuses without naming a party'),ce('right_party','Names a party on the right'),ce('left_party','Names a party on the left'));write_csv(itt,'results/intermediation/itt_response_effects.csv')
p<-ggplot(itt,aes(estimate,outcome,color=channel))+geom_vline(xintercept=0,color='#A0AEC0')+geom_errorbarh(aes(xmin=low,xmax=high),position=position_dodge(.5),height=0)+geom_point(position=position_dodge(.5),size=3)+scale_x_continuous(labels=percent_format())+scale_color_manual(values=c('#805AD5','#2B6CB0'))+labs(title='Voter wording changes whether and how chatbots answer',subtitle='Right minus left wording; 95% confidence intervals',x='Change in share of answers',y=NULL)+th;sv(p,'02_itt_effects.png')
cf<-c0%>%filter(conflict)%>%mutate(resolution=case_when(has_party&!is.na(zeta_sign)&zeta_sign==issue_num~'Follows policy',has_party&!is.na(zeta_sign)&zeta_sign==label_num~'Follows identity',has_party~'Party without clear side',refused2~'Refusal / no party',TRUE~'Other / no party'))%>%count(model,resolution)%>%group_by(model)%>%mutate(share=n/sum(n))%>%ungroup();write_csv(cf,'results/intermediation/conflict_full_distribution.csv')
p<-cf%>%mutate(model=factor(model,levels=rev(core)))%>%ggplot(aes(share,model,fill=resolution))+geom_col()+scale_y_discrete(labels=function(x)recode(x,!!!ml))+scale_x_continuous(labels=percent_format(),expand=c(0,0))+scale_fill_manual(values=c('#805AD5','#2B6CB0','#A0AEC0','#C53030','#718096'))+guides(fill=guide_legend(nrow=3,byrow=TRUE))+labs(title='Chatbots resolve identity-policy conflicts differently',subtitle='All answers from the two conflict conditions',x='Share of answers',y=NULL)+th+theme(legend.text=element_text(size=10));sv(p,'03_conflict_full.png',10.2,6.5)
cm<-c0%>%mutate(broad=case_when(has_party&!is.na(zeta)&zeta<0~'LEFT',has_party&!is.na(zeta)&zeta>=0~'RIGHT',has_party~'UNSCORED',refused2~'REFUSAL',TRUE~'OTHER'),exact=case_when(has_party~party_rec,refused2~'REFUSAL',TRUE~'OTHER'))%>%group_by(model,cond_id)%>%summarise(bm=names(sort(table(broad),decreasing=TRUE))[1],em=names(sort(table(exact),decreasing=TRUE))[1],.groups='drop')
pa<-map_dfr(combn(core,2,simplify=FALSE),function(q){a<-cm%>%filter(model==q[1])%>%select(cond_id,ba=bm,ea=em);b<-cm%>%filter(model==q[2])%>%select(cond_id,bb=bm,eb=em);inner_join(a,b,by='cond_id')%>%summarise(a=q[1],b=q[2],cells=n(),same_broad=mean(ba==bb),same_exact=mean(ea==eb))})%>%mutate(pair=paste(recode(a,!!!ml),recode(b,!!!ml),sep=' vs '));write_csv(pa,'results/intermediation/pairwise_model_agreement.csv')
st<-c0%>%mutate(response_type=case_when(has_party~'PARTY',refused2~'REFUSAL',TRUE~'OTHER'),side=case_when(has_party&!is.na(zeta)&zeta<0~'LEFT',has_party&!is.na(zeta)&zeta>=0~'RIGHT',has_party~'UNSCORED',refused2~'REFUSAL',TRUE~'OTHER'),exact=case_when(has_party~party_rec,refused2~'REFUSAL',TRUE~'OTHER'))%>%select(model,cond_id,response_type,side,exact)%>%pivot_longer(c(response_type,side,exact),names_to='level',values_to='value')%>%count(model,cond_id,level,value)%>%group_by(model,cond_id,level)%>%summarise(unanimous=max(n)==sum(n),modal=max(n)/sum(n),.groups='drop')%>%group_by(model,level)%>%summarise(unanimous=mean(unanimous),mean_modal=mean(modal),.groups='drop');write_csv(st,'results/intermediation/stability_by_level.csv')
bench<-tribble(~anchor,~lula,'militante_esquerda',97,'progressista',64,'classes_d_e',75,'liberal_social',65,'empreendedor_individual',50,'conservador_cristao',31,'agro',25,'empresario',25,'extrema_direita',0)
rich<-d%>%filter(model%in%core,usable,module=='anchor')%>%group_by(model,anchor)%>%summarise(z=mean(zeta,na.rm=TRUE),party=mean(has_party),refusal=mean(refused2),.groups='drop')%>%left_join(bench,by='anchor');write_csv(rich,'results/intermediation/rich_profiles_by_model.csv');rs<-rich%>%group_by(anchor,lula)%>%summarise(z=mean(z,na.rm=TRUE),party=mean(party),refusal=mean(refusal),.groups='drop');rho<-cor(rs$z,rs$lula,method='spearman',use='complete.obs');write_csv(rs,'results/intermediation/rich_profiles_summary.csv');write_lines(sprintf('Spearman rho = %.3f',rho),'results/intermediation/rich_profiles_validation.txt')
rs_plot<-rs%>%mutate(profile=recode(anchor,agro='Agribusiness',classes_d_e='Low income',conservador_cristao='Christian conservative',empreendedor_individual='Solo entrepreneur',empresario='Business owner',extrema_direita='Far right',liberal_social='Social liberal',militante_esquerda='Left activist',progressista='Progressive'))
p<-ggplot(rs_plot,aes(lula,z,label=profile))+geom_hline(yintercept=0,color='#CBD5E0')+geom_smooth(method='lm',se=FALSE,color='#A0AEC0')+geom_point(size=3.5,color='#2B6CB0')+geom_text(nudge_y=.035,size=3,check_overlap=TRUE)+labs(title='The profiles reproduce the political ordering of their source groups',subtitle=sprintf('Nine fictional profiles; Spearman correlation = %.2f',rho),x='Lula vote share in source group (2022, %)',y='Average position of named party')+th;sv(p,'05_rich_profile_validation.png')
write_csv(tibble(metric=c('module_c_usable','module_c_cells','mean_broad_agreement','mean_exact_agreement','rich_spearman'),value=c(nrow(c0),n_distinct(c0$cond_id),mean(pa$same_broad),mean(pa$same_exact),rho)),'results/intermediation/headline_metrics.csv')
